INSERT INTO `routes` VALUES (5,'Pradera Directo','Sale de Pradera Dorada pasando por UPSIN, El Conchi y Av. Gabriel Leyva hasta el Centro y Embarcadero Isla de la Piedra.','#ff0400',1,13,12,3.5),(6,'Lomas del Ébano Central','Baja de Lomas del Ébano y El Conchi por Av. Insurgentes, pasa por el IMSS, Central Camionera, Malecón y llega al Centro.','#1e88e5',1,13,20,3.5),(7,'Milenio Cerritos-Pradera','Conecta Pradera Dorada, UAS e ITMAZ con Plaza Acaya, Tecmilenio, La Marina y las playas de Cerritos.','#fb8c00',1,15,18,3.5),(8,'Sabalo Centro ','Recorre la zona hotelera desde Cerritos y Zona Dorada por todo el Malecón hasta Olas Altas, Playa Sur, Centro y Gran Acuario.','#4dff00',1,16,12,3.5),(9,'Villa Galaxia-Mañanitas','Pasa por Villa Galaxia, UPSIN, IMSS, Central Camionera, Malecón, Mercado Pino Suárez y Olas Altas.','#d81b60',1,15,17,3.5),(10,'San Joaquin Sabalo','Va de Pradera y UPSIN por Plaza Acaya, Zona Dorada y Av. Rafael Buelna (Valentino\'s, Sharp, Ley del Mar) hasta El Conchi.','#00acc1',1,15,13,3.5),(11,'Jabalies','Cruza desde Pradera y UPSIN por ISSSTE, IMSS, Central Camionera, Malecón, Olas Altas y el Mercado Pino Suárez.','#3949ab',1,13,14,3.5),(12,'Urias Sabalo','Sube desde Urías (ITMAZ, CETMAR, Conalep I) por Carretera Internacional y Av. Rafael Buelna directo hacia Zona Dorada y Valentino\'s.','#e100ff',1,15,15,3.5),(13,'Sirena','Conecta Urías, Conalep I y El Conchi con el IMSS, Central Camionera, Malecón, Centro y Terminal de Cruceros.','#2e7d32',1,15,14,3.5),(14,'Zapata Juarez','Sale de Pradera Dorada y Santa Rosa pasando por Col. Benito Juárez, Hospital Margarita Maza, Cruz Roja y Mercado Pino Suárez.','#0277bd',1,15,17,3.5),(16,'Centro Colonias','Conecta Urías (Conalep I) y Col. Benito Juárez con Av. Ejército Mexicano (IMSS, Central Camionera), Malecón, Mercado Pino Suárez, Catedral e ITMAZ.','#d671bb',1,13,22,3.5),(17,'Prados Del Sol','Sale de Prados del Sol, Centro de Convenciones y Galerías pasando por Carretera Internacional (ISSSTE, ICO), IMSS, Central Camionera, Centro Histórico y Plaza Acaya.','#ffc800',1,13,20,3.5),(18,'Cerritos Juarez','Recorre Cerritos, La Marina y Zona Dorada por Av. Rafael Buelna (Gran Plaza), IMSS, Soriana Insurgentes, Col. Benito Juárez, Blvd. Colosio y Mazagua.','#0049a8',1,15,13,3.5),(19,'Chololos Juarez','Conecta UPSIN, El Conchi y Col. Benito Juárez bajando por Av. Gabriel Leyva (Cruz Roja, JUMAPAM) hasta el Mercado Pino Suárez, Centro y Embarcadero.','#ffc3a3',1,13,22,3.5),(20,'Alarcón Sabalo','Une la zona norte (UAS Medicina, Plaza Acaya) por Libramiento y Av. Rafael Buelna (Plaza de Toros, Sharp) con Valentino\'s y toda la Zona Dorada.','#ff5500',1,15,14,3.5),(21,'Cocos Juárez','Cruza desde Col. Benito Juárez e Insurgentes por el IMSS, ISSSTE, Toreo y Av. Rafael Buelna hacia Zona Dorada, Galerías, Tecmilenio y Hospital General.','#bdd9ff',1,13,16,3.5),(22,'Parque Bonfil','Sale del Parque Industrial Bonfil pasando por Col. Benito Juárez, Av. Ejército Mexicano (IMSS, Central Camionera), Malecón, Mercado Pino Suárez y Centro.','#55007f',1,13,25,3.5),(23,'Hogar Del Pescador','Ruta de Águilas del Pacífico desde Pradera Dorada y Plaza Acaya por Carretera Internacional (ISSSTE, ICO), IMSS, Central Camionera, Mercado Pino Suárez y Centro Histórico.','#ffff00',1,13,20,3.5),(24,'Inf. Conchi','Conecta el Centro y Mercado Pino Suárez por Av. Ejército Mexicano (Central Camionera, IMSS), Col. Benito Juárez y Blvd. Colosio hasta Infonavit El Conchi.','#a65eba',1,13,15,3.5),(25,'Libramiento Juarez','Baja de Pradera Dorada y Santa Rosa por Libramiento y Blvd. Colosio cruzando Col. Benito Juárez y Av. Gabriel Leyva (Cruz Roja) hasta el Centro y Embarcadero.','#ff0184',1,13,18,3.5),(26,'Puertas Del Sol','Conecta Puertas del Sol, Pradera Dorada y Plaza Acaya por Carretera Internacional (ISSSTE, ICO), IMSS, Central Camionera y Centro Histórico.','#ff0000',1,13,20,3.5),(27,'San Joaquín Juárez','Une el Centro, Mercado Pino Suárez y Embarcadero por Av. Gabriel Leyva y Col. Benito Juárez hacia El Conchi, UPSIN, UAS Medicina y San Joaquín / Pradera.','#ff0000',1,15,18,3.5),(28,'Valle Del Ejido Alarcón','Sale de Valle del Ejido y Alarcón por Carretera Internacional (ISSSTE, ICO, Plaza El Mar), IMSS, Central Camionera, Mercado Pino Suárez y Centro Histórico.','#f1f100',1,15,19,3.5),(29,'Villas Del Rey','Enlaza el Centro, Catedral y Mercado Pino Suárez pasando por Monumento al Pescador, Mercado Juan Carrasco, Col. Benito Juárez, Toledo Corro y Villas del Rey.','#ff55ff',1,13,24,3.5),(30,'Lomas Juárez','Recorre del Centro y Mercado Pino Suárez por Av. Gabriel Leyva, Col. Benito Juárez y Blvd. Colosio hasta El Conchi, Mercado Flores Magón y Lomas.','#0000ff',1,13,20,3.5),(31,'Insurgentes','Una de las troncales principales: pasa por Blvd. Colosio, Toledo Corro, Av. Insurgentes, IMSS, Central Camionera, Mercado Pino Suárez y Centro Histórico.','#ff4b2b',1,15,11,3.5),(32,'Chulavista','Conecta Chulavista, Plaza de Toros y Av. Rafael Buelna (Sharp, Gran Plaza) con IMSS, Central Camionera, Malecón, Mercado Pino Suárez y Playa Sur.','#ff4b2b',1,13,22,3.5);
